cd /home/factory-user/repos/finnor-z-coordinator && node --input-type=module <<'NODE'
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { stripTypeScriptTypes } from "node:module";
// Failure model: a valid semantic Work ID is removed by the public envelope.
// Economic reader is the positive control. This is not HTTP/auth/DB execution.
const paths = {
  route: "finnor-os/apps/api/app/api/queries/route.ts",
  fast: "finnor-os/packages/orchestration/src/fast-read-lane.ts",
  queries: "finnor-os/packages/shared-types/src/operational-queries.ts",
  retired: "finnor-os/packages/shared-types/src/retired-water.ts",
  registry: "finnor-os/packages/orchestration/src/plugin-registry.ts",
  economic: "finnor-os/packages/private-equity/src/program-synthesis/economic-native.ts",
  manifest: "src/lib/centropy/capability-manifest.generated.json",
};
const s = Object.fromEntries(Object.entries(paths).map(([k,p]) => [k,readFileSync(p,"utf8")]));
const js = source => stripTypeScriptTypes(source).replace(/^export /gm,"");
const retiredJS = js(s.retired);
assert(!/^import\s/m.test(retiredJS));
const retired = new Function(retiredJS + ";return {isRetiredWaterQuery,isRetiredWaterParty,isRetiredWaterCanonicalEntity};")();
const queryCode = s.queries.slice(s.queries.indexOf("export const CORE_OPERATIONAL_QUERY_INTENTS"),s.queries.indexOf("export type CoreOperationalQueryIntent"));
const lists = new Function(js(queryCode) + ";return {OPERATIONAL_QUERY_INTENTS,PRIVATE_EQUITY_OPERATIONAL_QUERY_INTENTS};")();
const uuid = s.fast.match(/^const UUID = .*;$/m)?.[0];
assert(uuid);
const validatorCode = s.fast.slice(s.fast.indexOf("function object("),s.fast.indexOf("\nexport function classifyFastReadOnlyQuestion"));
assert(validatorCode.includes("export function validateOperationalQueryRequest"));
const validate = new Function("ACTIVE_INTENTS","PE_INTENTS","isRetiredWaterQuery","isRetiredWaterParty","isRetiredWaterCanonicalEntity",
  js(uuid + "\n" + validatorCode) + ";return validateOperationalQueryRequest;")(
  new Set(lists.OPERATIONAL_QUERY_INTENTS),new Set(lists.PRIVATE_EQUITY_OPERATIONAL_QUERY_INTENTS),
  retired.isRetiredWaterQuery,retired.isRetiredWaterParty,retired.isRetiredWaterCanonicalEntity);
const parserCode = s.route.slice(s.route.indexOf("function isRecord("),s.route.indexOf("export async function POST"));
assert(parserCode.includes("function parseRequestBody"));
const parse = new Function("validateOperationalQueryRequest",js(parserCode) + ";return parseRequestBody;")(validate);
const workId = "11111111-1111-4111-8111-111111111111";
const id = "22222222-2222-4222-8222-222222222222";
const cases = [
  {intent:"harness_program_v1",programId:id,workId},
  {intent:"economic_programme_v1",programmeId:id,workId},
  {intent:"confidential_economic_computation_v1",workId},
];
const observations = cases.map(input => ({intent:input.intent,direct:validate(input),publicEnvelope:parse(input)}));
assert(observations.every(x => x.direct.success));
assert.deepEqual(observations.map(x => x.publicEnvelope.success),[false,true,false]);
const manifest = JSON.parse(s.manifest);
const planner = manifest.capabilities.filter(x => x.transport === "planner");
const names = new Set(planner.map(x => x.capabilityId.replace(/^planner\./,"")));
const canonical = ["clarification_request","search_web","computer_task","wait:event","check:objective_success","execute_economic_right_transition"];
for (const name of canonical) assert((name === "execute_economic_right_transition" ? s.economic : s.registry).includes('"' + name + '"') || s.economic.includes("'" + name + "'"));
const omitted = canonical.filter(name => !names.has(name));
assert.deepEqual(omitted,canonical);
const contexts = cases.map(x => ({intent:x.intent,requiredContext:planner.find(c => c.capabilityId === "planner.query:" + x.intent)?.requiredContext}));
assert.deepEqual(contexts.map(x => x.requiredContext),[["workId","programId"],[],[]]);
console.log(JSON.stringify({
  scope:"READ_ONLY_EXTRACTED_SOURCE_CONTRACT_REPLAY_NOT_HTTP_OR_RUNTIME_QUALIFICATION",
  observations,catalogue:{http:manifest.capabilities.filter(x=>x.transport==="http").length,planner:planner.length,omitted,contexts},
  sourceDigests:Object.entries(paths).map(([k,path])=>({path,sha256:createHash("sha256").update(s[k]).digest("hex")})),
  result:"PASS"
},null,2));
